import random, json, re
random.seed(1001)
# Engine: generate an OpenAPI-ish spec from a resource list, then validate it.
resources=["books","authors"]
spec={"openapi":"3.0.0","info":{"title":"Demo API","version":"1.0.0"},"paths":{}}
for res in resources:
    spec["paths"][f"/{res}"]={"get":{"summary":f"List {res}","responses":{"200":{"description":"OK"}}},
                              "post":{"summary":f"Create {res}","responses":{"201":{"description":"Created"}}}}
    spec["paths"][f"/{res}/{{id}}"]={"get":{"summary":f"Get {res} by id","responses":{"200":{"description":"OK"},"404":{"description":"Not found"}}}}
# validate: paths start with /, methods known, ids templated
ok=True; msgs=[]
for p,ops in spec["paths"].items():
    if not p.startswith("/"): ok=False; msgs.append(p)
    for m in ops:
        if m not in ("get","post","put","delete","patch"): ok=False; msgs.append(m)
print(f"resources={resources} paths={len(spec['paths'])}")
print("spec_json_bytes=", len(json.dumps(spec)))
print(f"validation={'PASS' if ok else 'FAIL '+str(msgs)}")
print("DEMO_OK")

